package hr.mentalblue.retadnevnik;
import android.app.Activity;import android.os.Bundle;import android.widget.*;
public class PrivacyActivity extends Activity {public void onCreate(Bundle b){super.onCreate(b);TextView t=new TextView(this);t.setPadding(40,60,40,40);t.setTextSize(17);t.setText("Reta Log · Health data privacy\n\nReta Log reads only health categories you permit, to preview and import your body measurement history. Data is stored in the app private storage on this phone. It is not uploaded by Reta Log.\n\nYou may revoke permissions in Health Connect. Imported copies stay in Reta Log until you delete them, undo the import, or uninstall the app. Manually exported backups and reports contain readable health information.\n\nBiometric locking is optional in Settings. This journal does not recommend medication doses.");setContentView(t);}}
